"""Adapt the pinned Matrix.js assertions to the public affine decomposition API."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[2]
fixtures = json.loads((root / 'scripts/paperjs/matrix.json').read_text())['fixtures']

def number(value):
    text = repr(float(value))
    return text.replace('e+', 'e')

def matrix(f):
    return 'affine.Affine(' + ', '.join(map(number, f['matrix'])) + ')'

header = '''// Adapted from pinned Paper.js Matrix.js (MIT; see scripts/paperjs/upstream/LICENSE.txt).
// Generated by scripts/paperjs/generate-matrix.py; fixture IDs match matrix.json.
'''
probe = [header, '''import gleam/float
import gleam/io
import gleam/string
import svg_path/affine
fn emit(id: String, m: affine.Affine) {
  let output = case affine.decompose(m) {
    Ok(f) -> float.to_string(f.rotation_degrees) <> "," <> float.to_string(f.scale_x) <> "," <> float.to_string(f.scale_y)
    Error(error) -> string.inspect(error)
  }
  io.println(id <> ":" <> output)
}
pub fn main() {''']
tests = [header, '''import gleam/float
import gleam/option.{None}
import svg_path/affine
import svg_path/transform
import svg_path/transform/parse
import svg_path/transform/serialize

fn close(actual: Float, expected: Float) {
  assert float.absolute_value(actual -. expected) <=. 1.0e-10
}

fn column_close(a: Float, b: Float, x: Float, y: Float) {
  let scale = float.max(float.absolute_value(a), float.absolute_value(b))
  case scale >. 0.0 {
    True -> {
      assert float.absolute_value(a /. scale -. x /. scale) <=. 1.0e-12
      assert float.absolute_value(b /. scale -. y /. scale) <=. 1.0e-12
    }
    False -> { close(x, 0.0) close(y, 0.0) }
  }
}

fn matrix_close(actual: affine.Affine, expected: affine.Affine) {
  column_close(expected.a, expected.b, actual.a, actual.b)
  column_close(expected.c, expected.d, actual.c, actual.d)
  column_close(expected.e, expected.f, actual.e, actual.f)
}

fn check_round_trips(m: affine.Affine, f: affine.Decomposition) {
  matrix_close(affine.recompose(f), m)
  close(f.shear_x, 0.0)
  let transform = m |> affine.to_tuple |> transform.from_tuple
  let options = serialize.Options(None, False, False)
  let assert Ok(pretty) = parse.attribute(serialize.to_string_with(transform, options:))
  matrix_close(pretty |> transform.to_tuple |> affine.from_tuple, m)
  let assert Ok(ordered) = serialize.to_string_in_order(transform,
    order: affine.TranslationRotationShearXScale, options:)
  let assert Ok(parsed) = parse.attribute(ordered)
  matrix_close(parsed |> transform.to_tuple |> affine.from_tuple, m)
}
''']
for f in fixtures:
    probe.append(f'emit("{f["id"]}", {matrix(f)})')
    tests.append(f'// Paper.js: {f["message"]}\npub fn paper_matrix_{f["id"]}_test() {{\n  let m = {matrix(f)}\n  let assert Ok(f) = affine.decompose(m)')
    if f['method'] == 'getRotation':
        expected = f['expected']
        if expected == -180:
            tests.append('  // Equivalent endpoint convention: affine uses (-180,180], so -180 becomes +180.')
            expected = 180
        tests.append(f'  close(f.rotation_degrees, {number(expected)})\n  check_round_trips(m, f)')
    else:
        tests.append(f'  close(f.scale_x, {number(f["expected"][0])})\n  close(f.scale_y, {number(f["expected"][1])})')
    tests.append('}')
probe.append('}')
(root / 'test_paperjs/src/paper_matrix_probe.gleam').write_text('\n'.join(probe) + '\n')
(root / 'test/svg_path_paper_matrix_test.gleam').write_text('\n'.join(tests) + '\n')
